private string EncodingFileName(string name)
		{
			byte[] bytes = Encoding.UTF8.GetBytes(name);
			byte[] newBytes = Encoding.Convert(Encoding.UTF8, Encoding.GetEncoding(1251), bytes);
			string fileName = Encoding.GetEncoding(866).GetString(newBytes);
			return fileName;
		}

