namespace JetCalendar
{
	public class CalendarUtils
	{
		private UserConnection userConnection { get; set; }
		public CalendarUtils(UserConnection userConnection)
		{
			this.userConnection = userConnection;
		}
		public DateTime AddWorkDays(DateTime now, int days, Guid calendarId)
		{
			var resultDay = now;
			for (int i = 0; i < days; i++)
			{
				resultDay = resultDay.AddDays(1);
				if (!IsWorkday(resultDay, calendarId))
				{
					i--;
				}
			}

			return resultDay;
		}

		public bool IsWorkday(DateTime dtNow, Guid calendarId)
		{
			Guid dayoff = new Guid("078C9B1E-9312-43EF-B890-E5298DB62827");
			Guid workDay = new Guid("e0c666ad-a59e-4625-89e6-5e0bf75dad2a");

			var selectDayType = new Select(userConnection)
				.Column("DayTypeId")
				.From("DayOff")
				.Where("Date").IsEqual(Column.Parameter(dtNow.Date))
				.And("CalendarId").IsEqual(Column.Parameter(calendarId)) as Select;
			var dayTypeId = selectDayType.ExecuteScalar<Guid>();

			var selectCalendarDayType = new Select(userConnection)
				.Column("DayTypeId")
				.From("DayInCalendar")
				.Join(JoinType.Inner, "DayOfWeek").On("DayOfWeek", "Id").IsEqual("DayInCalendar", "DayOfWeekId")
				.Where("DayOfWeek", "Code").IsEqual(Column.Parameter(dtNow.DayOfWeek.ToString()))
				.And("DayInCalendar", "CalendarId").IsEqual(Column.Parameter(calendarId)) as Select;
			var calendarDayTypeId = selectCalendarDayType.ExecuteScalar<Guid>();

			bool isWorkday = true;

			if (dayTypeId.Equals(dayoff))
			{
				isWorkday = false;
			}
			else if (dayTypeId.Equals(workDay))
			{
				isWorkday = true;
			}
			else if (calendarDayTypeId.Equals(dayoff))
			{
				isWorkday = false;
			}

			return isWorkday;
		}
	}
}

