		public void CopyDataFromFormToContact(Guid formId, Guid contactId)
		{
			var formValues = GetFormValues(formId);

			var esq = new EntitySchemaQuery(UserConnection.EntitySchemaManager, "Contact");
			esq.AddAllSchemaColumns();
			var ent = esq.GetEntity(UserConnection, contactId);

			var contactCols = FormContactMapping.ContactConfig.Where(c => string.IsNullOrEmpty(c.SubFilterSchema));

			SetEntityColumnValues(ent, formValues, contactCols.ToList());
			ent.Save();

			var subSchemas = FormContactMapping.ContactConfig
				.Where(c => !string.IsNullOrEmpty(c.SubFilterSchema))
				.Select(c => c.SubFilterSchema + JsonConvert.SerializeObject(c.Filters))
				.Distinct();

			foreach (var subSchema in subSchemas)
			{
				var subSchemaCols = FormContactMapping.ContactConfig.Where(c => c.SubFilterSchema + JsonConvert.SerializeObject(c.Filters) == subSchema);
				var filters = subSchemaCols.First().Filters;
				var schemaName = subSchemaCols.First().SubFilterSchema;

				EntitySchema subEntitySchema = UserConnection.EntitySchemaManager.GetInstanceByName(schemaName);
				var subEntity = subEntitySchema.CreateEntity(UserConnection);

				var mainFilterKey = filters.FirstOrDefault(f => f.Value.ToString() == "ContactId").Key;
				if (!string.IsNullOrEmpty(mainFilterKey))
				{
					filters[mainFilterKey] = contactId;
				}

				var schemaColumns = subEntity.Schema.Columns;
				if (!subEntity.FetchFromDB(filters))
				{
					subEntity.SetDefColumnValues();
					foreach (var condition in filters)
					{
						var colName = condition.Key;
						var column = schemaColumns.GetByName(colName);
						if (column.DataValueType.IsLookup)
						{
							colName += "Id";
						}
						subEntity.SetColumnValue(colName, condition.Value);
					}
				}

				SetEntityColumnValues(subEntity, formValues, subSchemaCols.ToList());
				subEntity.Save();
			}
		}

