		public static void UpdateCase (UserConnection userConnection)
    	{
			List<CaseEOL> resultList = new List<CaseEOL>();
			var select = new Select(userConnection)
                .Column("Case", "Id")
				.Column("ServicePact", "SibEOLId")
				.From("Case")
                .Join(JoinType.Inner, "ServicePact")
                .On("ServicePact", "Id").IsEqual("Case", "ServicePactId")
				.Where("Case", "SibEOLId").IsNull()
				.Or("Case", "SibEOLId").IsNotEqual("ServicePact", "SibEOLId") as Select;

			string sqlText = select.GetSqlText();			
			using (DBExecutor dbExec = userConnection.EnsureDBConnection())
			{
				using (IDataReader reader = select.ExecuteReader(dbExec))
				{
					while (reader.Read())
					{
						resultList.Add(
							new CaseEOL(
								reader.GetColumnValue<Guid>("Id"),
								reader.GetColumnValue<Guid>("SibEOLId")
								)
							);
					}
				}
			}
			if (resultList.Count > 0)
			{
				foreach (var item in resultList)
				{
					var update = new Update(userConnection, "Case")
					.Set("SibEOLId", Column.Const(item.EOLId))
					.Where("Id").IsEqual(Column.Const(item.CaseId)) as Update;
					update.Execute();
				}
			}

		}
