namespace SibUtils
{
	/// <summary>
	/// Класс содержит методы расширения UserConnection, которые позволяют перезагружать страницу и раздел у пользователя.
	/// </summary>
	public static class EntityReloadUtilities
	{
		/// <summary>
		/// Перезагружает страницу выбранного объекта у текущего пользователя.
		/// </summary>
		/// <param name="userConnection">UserConnection.</param>
		/// <param name="entitySchemaName">Название схемы объекта.</param>
		/// <param name="entityId">Идентификатор объекта.</param>
		public static void ReloadEntityPage(this UserConnection userConnection, string entitySchemaName, Guid entityId)
		{
			string msg = string.Format("{{\"entitySchemaName\":\"{0}\", \"entityId\":\"{1}\"}}",
				entitySchemaName,
				entityId.ToString().ToLower());
			MsgChannelUtilities.PostMessage(userConnection, "ReloadEntityPage", msg);
		}

		/// <summary>
		/// Перезагружает выбранный раздел у текущего пользователя.
		/// </summary>
		/// <param name="userConnection">UserConnection.</param>
		/// <param name="entitySchemaName">Название схемы объекта.</param>
		public static void ReloadSection(this UserConnection userConnection, string entitySchemaName)
		{
			string msg = string.Format("{{\"entitySchemaName\":\"{0}\"}",
				entitySchemaName);
			MsgChannelUtilities.PostMessage(userConnection, "ReloadSection", msg);
		}

		/// <summary>
		/// Перезагружает страницу выбранного объекта у текущего пользователя.
		/// </summary>
		/// <param name="userConnection">UserConnection.</param>
		/// <param name="entitySchemaName">Название схемы объекта.</param>
		/// <param name="entityId">Идентификатор объекта.</param>
		/// <param name="columns">Список колонок для обновления.</param>
		public static void ReloadEntityColumns(this UserConnection userConnection, string entitySchemaName, Guid entityId, params string[] columns)
		{
			string msg = string.Format("{{\"entitySchemaName\":\"{0}\", \"entityId\":\"{1}\", \"columns\": [\"{2}\"] }}",
				entitySchemaName,
				entityId.ToString().ToLower(),
				string.Join("\", \"", columns));
			MsgChannelUtilities.PostMessage(userConnection, "ReloadEntityColumns", msg);
		}
	}
}

