private List<Guid> GetExpired()
{
	Select select = new Select(UserConnection)
		.Column("Id")
		.From(nameof(MscBehavioralFeatureAssignment))
		.Where(nameof(MscBehavioralFeatureAssignment.MscStatusId))
			.IsEqual(Column.Parameter(BehavioralFeature.AssignmentStatus.Active))
		.And(nameof(MscBehavioralFeatureAssignment.MscUnlockDate))
			.IsLess(Column.Parameter(DateTime.Today.AddDays(1))) as Select;
	return select.ExecuteEnumerable(r => r.GetColumnValue<Guid>("Id")).ToList();
}

private void Deactivate(List<Guid> list)
{
	Update update = new Update(UserConnection, nameof(MscBehavioralFeatureAssignment));
	update.Set(nameof(MscBehavioralFeatureAssignment.MscStatusId), Column.Parameter(BehavioralFeature.AssignmentStatus.Inactive));
	update.Where("Id").In(Column.Parameters(list));
	update.Execute();
}

