	[EntityEventListener(SchemaName = "Lead")] //от какой схемы нужно делать EventListener
	public class LeadEventListenerForBusinessProcess : BaseEntityEventListener 
	{
		public override void OnSaving(object Lead, EntityBeforeEventArgs e) 
		{
			var entity = (Entity)Lead; // Entity - явная типизация

			if (entity.GetTypedOldColumnValue<Guid>("QualifyStatusId") == QualifyStatusConst.AdditionalRequest &&
				entity.GetTypedColumnValue<Guid>("QualifyStatusId") == QualifyStatusConst.TakenWork) //сраниваем старое значение с новым
			{
				JetActivitiesProcessInWorkRequestStart(entity.PrimaryColumnValue, entity.UserConnection);
			}				
				base.OnSaving(Lead, e); //обязательный вызов базоваого метода
		}

		private void JetActivitiesProcessInWorkRequestStart(Guid LeadId, UserConnection userConnection)
		{

			Dictionary<string, string> parameterValues = new Dictionary<string, string> //наполняю словарь параметров для БП
			{
				["LeadId"] = LeadId.ToString() //название параметра бизнес-процесса
			};
			ProcessSchema schema = userConnection.ProcessSchemaManager.GetInstanceByName("JetActivitiesProcessInWorkRequestStart"); //вызов БП
			userConnection.ProcessEngine.ProcessExecutor.Execute(schema.UId, parameterValues); //вызов БП с передачей параметров
		}

	}	
}

