}

---метод JsonConvert.SerializeObject(array) создает нормальный JSON---
public string CreateCommentVkus(string sourceUUID, string text, string entityToCreate = "comment")
{
	var resultUUID = "";
	string uri = $"{NaumenURL}create-m2m/{entityToCreate}?accessKey={NaumenAccessKey}";

	using (var client = new WebClient())
	{
		client.Headers.Add("user-agent", "Mozilla/4.0 (compatible; MSIE 6.0; Windows NT 5.2; .NET CLR 1.0.3705;)");
		client.Headers["content-type"] = "application/json";
		var formatJSON = new Dictionary<string, string> 
		{
			["source"] = sourceUUID,
			["text"] = text
		};
		string requestParams = JsonConvert.SerializeObject(formatJSON);//вот он
		byte[] request = Encoding.UTF8.GetBytes(requestParams);
		byte[] responseByte = client.UploadData(uri, "post", request);
		var responseStr = Encoding.Default.GetString(responseByte);
		dynamic response = JsonConvert.DeserializeObject(responseStr);
		resultUUID = response.UUID;

		Sibur.Logging.LogRouter.Log("For sourceUUID: " + sourceUUID + " response received: " + responseStr, Sibur.Logging.LogLevel.Debug, "NSD_Cases");
	}

	return resultUUID;
}

