using ModuleDefinition = Mono.Cecil.ModuleDefinition;

public class CecilInterfaceAnalyzer
{
    public static void FindInterfaceInheritance(string dllPath, string interfaceName)
    {
        var module = ModuleDefinition.ReadModule(dllPath);

        foreach (var type in module.Types)
        {
            if (type.IsClass)
            {
                if (type.Interfaces.Count > 0)
                {
                    if (!type.Interfaces.Any((inte) => inte.InterfaceType.Name == interfaceName))
                    {
                        continue;
                    }
                    Console.WriteLine($"Класс: {type.FullName}");
                    Console.WriteLine("  Наследует интерфейсы:");
                    foreach (var interfaceImpl in type.Interfaces)
                    {
                        Console.WriteLine($"    - {interfaceImpl.InterfaceType.FullName}");
                    }
                }
            }
        }
    }
}

