define("BasePageV2", [], function () {
	return {
		methods: {
			/**
			 * @overridden
			 */
			init: function () {
				this.callParent(arguments);
				this.subscribeReloadEntityEvent();
			},

			/**
			 * Подписка на серверные события.
			 * @protected
			 */
			subscribeReloadEntityEvent: function () {
				this.Terrasoft.ServerChannel.on(
					this.Terrasoft.EventName.ON_MESSAGE,
					this.onServerChannelMessageEvent,
					this
				);
			},

			/**
			 * Отписка от серверных событий.
			 * @protected
			 */
			unsubscribeReloadEntityEvent: function () {
				this.Terrasoft.ServerChannel.un(
					this.Terrasoft.EventName.ON_MESSAGE,
					this.onServerChannelMessageEvent,
					this
				);
			},

			/**
			 * Обработчик серверного сообщения.
			 * @param {Object} scope Message scope.
			 * @param {Object} message Server messsage.
			 */
			onServerChannelMessageEvent: function (scope, message) {
				if (message?.Header?.Sender === "ReloadEntityPage") {
					var receivedMessage = this.Ext.decode(message.Body);
					if (
						receivedMessage.entitySchemaName ===
							this.entitySchemaName &&
						receivedMessage.entityId === this.$Id
					) {
						this.reloadEntity();
					}
				}
			},

			/**
			 * @inheritdoc Terrasoft.BaseSchemaViewModel#destroy
			 * @overridden
			 */
			destroy: function () {
				this.unsubscribeReloadEntityEvent();
				this.callParent(arguments);
			},
		},
	};
});

