    using CoreSysSettings = Terrasoft.Core.Configuration.SysSettings;

    #region Class: SysSettingsService

    [ServiceContract]
    [AspNetCompatibilityRequirements(RequirementsMode = AspNetCompatibilityRequirementsMode.Required)]
    public class SysSettingsService : BaseService
    {
        #region Constructors: public

        public SysSettingsService() : base() { }

        public SysSettingsService(UserConnection userConnection) : base(userConnection) { }

        #endregion

        #region Methods: Public

        public int GetCurrentValue(string JetOrderLastNumber)
        {
            if (GlobalAppSettings.UseDBSequence)
            {
                var sequenceMap = new SequenceMap(UserConnection);
                Sequence sequence = sequenceMap.GetByNameOrDefault(JetOrderLastNumber);
                return sequence.GetNextValue();
            }
            var coreSysSettings = new CoreSysSettings(UserConnection);
            if (coreSysSettings.FetchFromDB("Code", JetOrderLastNumber))
            {
                object value = coreSysSettings.DefValue;
                int sysSettingsLastNumber = value is int
                    ? (int)value
                    : Decimal.ToInt32((decimal)value);
                coreSysSettings.DefValue = ++sysSettingsLastNumber;
                coreSysSettings.Save();
                return sysSettingsLastNumber;
            }
            return -1;
        }

        [OperationContract]
        [WebInvoke(Method = "POST", BodyStyle = WebMessageBodyStyle.Wrapped,
            RequestFormat = WebMessageFormat.Json, ResponseFormat = WebMessageFormat.Json)]
        public string GetCurrentValueVsMask(string JetOrderLastNumber, string JetOrderCodeMask)
        {
            string sysSettingsCodeMask = (string)CoreSysSettings.GetValue(UserConnection, JetOrderCodeMask);
            int value = GetCurrentValue(JetOrderLastNumber);
            return String.Format(sysSettingsCodeMask, value);
        }

        #endregion
    }

    #endregion
}

