namespace Terrasoft.Configuration
{
	using System;
    using Terrasoft.Core;
    using Terrasoft.Core.Entities.AsyncOperations;
    using Terrasoft.Core.Entities.AsyncOperations.Interfaces;
	using System.Collections.Generic;
	using Terrasoft.Core.Entities;

	public class SendCalculateMatrixAsyncExecutor : IEntityEventAsyncOperation
	{
		public void Execute(UserConnection userConnection, EntityEventAsyncOperationArgs arguments) 
		{
			var householdId = GetHouseholdId(userConnection, arguments.EntitySchemaName, arguments.EntityId);
			if (householdId != Guid.Empty)
			{
				new PrbMatrixHelper.PrbMatrixHelper(userConnection).PostCalculateOne(householdId);
			}
		}

		private static Dictionary<string, string> _pathToHouseholdId = new Dictionary<string, string>
		{
			{"PrbHousehold", "Id"},
			{"PrbTelevision", "PrbDevice.PrbLocation.PrbHousehold.Id"},
			{"Contact", "PrbHousehold.Id"},
			{"PrbLocation", "PrbHousehold.Id"},
			{"PrbContactInResearch", "PrbRespondent.PrbHousehold.Id"}
		};

		public static Guid GetHouseholdId(UserConnection userConnection, string entitySchemaName, Guid entityId)
		{
			if (_pathToHouseholdId.TryGetValue(entitySchemaName, out string column))
			{
				if (column.Equals("Id")) return entityId;
				var esq = new EntitySchemaQuery(userConnection.EntitySchemaManager, entitySchemaName)
				{
					UseAdminRights = false,
					UseLocalization = false,
					IgnoreDisplayValues = true,
					RowCount = 1
				};

				var columnName = esq.AddColumn(column).Name;
				esq.Filters.Add(esq.CreateFilterWithParameters(FilterComparisonType.Equal, "Id", entityId));
				var entityCollection = esq.GetEntityCollection(userConnection);

				if (entityCollection.Count > 0)
				{
					return entityCollection[0].GetTypedColumnValue<Guid>(columnName);
				}
			}
			else
			{
				throw new Exception(
						$"Для объекта {entitySchemaName} не предусмотрен обработчик асинхронного выполнения SendCalculateMatrix");
			}
			return Guid.Empty;
		}
	}
}

