		public string AddLicenseInfo(string userId, string licenseItems)
		{
			try
			{
				Dictionary<string, bool> licenses = Json.Deserialize<Dictionary<string, bool>>(licenseItems);
				foreach (KeyValuePair<string, bool> licItem in licenses)
				{
					var userName = GetNameByTable(new Guid(userId), "SysAdminUnit");
					var licName = GetNameByTable(new Guid(licItem.Key), "SysLicPackage");
					var isAddMode = licItem.Value;
					var description = GetDescriptionByLicenseInfo(userName, licName, isAddMode);
					CreateNewAuditRecord(description, isAddMode);
				}
			}
			catch (Exception ex)
			{
				return ex.Message;
			}
			return "";
		}

		public string GetNameByTable(Guid Id, string tableName)
		{
			var esq = new EntitySchemaQuery(UserConnection.EntitySchemaManager, tableName)
			{
				UseAdminRights = false,
				UseLocalization = false,
				IgnoreDisplayValues = true,
				RowCount = 1
			};

			var columnName = esq.AddColumn("Name").Name;
			esq.Filters.Add(esq.CreateFilterWithParameters(FilterComparisonType.Equal, "Id", Id));
			var entityCollection = esq.GetEntityCollection(UserConnection);

			if (entityCollection.Count > 0)
			{
				return entityCollection[0].GetTypedColumnValue<string>(columnName);
			}
			return "";
		}

		public void CreateNewAuditRecord(string description, bool isAddMode)
		{

			var result = isAddMode == true ? new Guid("de1db6e0-baad-4acf-a521-52cef05b592e") : new Guid("b9cfd741-b528-4c2b-9e11-dbbae0032828");
			var currentContactId = UserConnection.CurrentUser.ContactId;
			var now = DateTime.UtcNow;
			Insert insert = new Insert(UserConnection).Into("SysOperationAudit")
				.Set("CreatedOn", Column.Parameter(now))
				.Set("ModifiedOn", Column.Parameter(now))
				.Set("Date", Column.Parameter(now))
				.Set("ModifiedById", Column.Parameter(currentContactId))
				.Set("CreatedById", Column.Parameter(currentContactId))
				.Set("OwnerId", Column.Parameter(currentContactId))
				.Set("ResultId", Column.Parameter(result))
				.Set("Description", Column.Parameter(description))
				.Set("ClientIP", Column.Parameter(UserConnection.CurrentUser.ClientIP))
				.Set("TypeId", Column.Parameter(new Guid("1b33498a-4b35-4d33-9881-77b6a6ab171f"))); //     SysOperationType   " "   
			insert.Execute();
		}

		public string GetDescriptionByLicenseInfo(string userName, string licName, bool isAddMode)
		{
			var operation = isAddMode == true ? "added" : "deleted";			
			return $"License \"{licName}\" has been {operation} to the user {userName}.";
		}
	}
}

