namespace Terrasoft.Configuration.BnzMain
{
	[DefaultBinding(typeof(IBusinessProcessUtility))]
	public class BnzBusinessProcessUtility : IBusinessProcessUtility
	{
		protected UserConnection UserConnection { get; }
		protected IProcessEngine ProcessEngine { get; }
		protected IProcessExecutor ProcessExecutor { get; }
		public Guid EntityId { get; set; }

		public BnzBusinessProcessUtility(UserConnection userConnection) {
			UserConnection = userConnection;
			ProcessEngine = userConnection.ProcessEngine;
			ProcessExecutor = ProcessEngine.ProcessExecutor;
		}
		protected virtual Select GetRunningProcessIdByEntitySelect(Guid entityId) {
			return new Select(UserConnection)
				.Column("pe","SysProcessId")
				.From("VwSysProcessEntity").As("pe")
				.InnerJoin("VwSysProcessLog").As("pl").On("pl", "Id").IsEqual("pe", "SysProcessId")
				.Where("pe","EntityId").IsEqual(Column.Parameter(entityId)) 
				.And("pl", "StatusId").IsEqual(Column.Parameter(BnzCsConsts.SysProcessStatus.Running)) as Select;
		}
		public Process GetParentProcess(Process process) {
			Process parentProcess = process.GetParentProcess();
			return parentProcess == null ? parentProcess :
				parentProcess.UId != process.UId && parentProcess.InstanceUId != process.InstanceUId ? parentProcess :
				null;
		}
		public Process GetProcessById(Guid processId) {
			return ProcessEngine.FindProcessByUId(processId.ToString(), true);
		}
		public void CancelExecution(Guid processId) {
			Process process = GetProcessById(processId);
			if (process != null && process.Status == ProcessStatus.Running) {
				Process parentProcess = GetParentProcess(process);
				if (parentProcess != null && parentProcess.Status == ProcessStatus.Running) {
					CancelExecution(parentProcess.UId);
				}
				process.CancelExecution();
			}
		}

		public void RunProcessByQuartz(string processName, Dictionary<string, object> parameters) {
			Guid currentUserId = UserConnection.CurrentUser.Id;
			var jobName = $"{processName}_{currentUserId}_{EntityId}_Job";
			var jobGroup = $"{processName}_Group";
			AppScheduler.ScheduleImmediateProcessJob(jobName, jobGroup, processName, UserConnection.Workspace.Name,
				UserConnection.CurrentUser.Name, parameters);
		}

		public void RunProcess(string processName, Dictionary<string, string> parameters) {
			ProcessExecutor.Execute(processName, parameters);
		}

		public TResult RunProcess<TResult>(string processSchemaName, string resultParameterName, IReadOnlyDictionary<string, string> parameterValues = null) {
			return ProcessExecutor.Execute<TResult>(processSchemaName, resultParameterName, parameterValues);
		}

		public List<Guid> GetRunningProcessesIdByEntity(Guid entityId) {
			var processesIdsList = new List<Guid>();
			Select select = GetRunningProcessIdByEntitySelect(entityId);
			select.ExecuteReader(reader => processesIdsList.Add(reader.GetColumnValue<Guid>("SysProcessId")));
			return processesIdsList;
		}
	}
	public interface IBusinessProcessUtility
	{
		Guid EntityId { get; set; }
		void CancelExecution(Guid processId);
		void RunProcessByQuartz(string processName, Dictionary<string, object> parameters);
		void RunProcess(string processName, Dictionary<string, string> parameters);
		TResult RunProcess<TResult>(string processSchemaName, string resultParameterName, IReadOnlyDictionary<string, string> parameterValues = null);
		List<Guid> GetRunningProcessesIdByEntity(Guid entityId);
	}
}

