	[EntityEventListener(SchemaName = "PortalMessage")]
	public class SibPortalMessageEventListener : BaseEntityEventListener
	{
		public CaseInfo caseInfo = new CaseInfo();

		#region Methods: Public
		public override void OnInserted(object sender, EntityAfterEventArgs e)
		{
			base.OnInserted(sender, e);
			var entity = (PortalMessage)(Entity)sender;
			var userConnection = entity.UserConnection;
			var id = entity.EntityId;
			var portalMessage = entity.Message;
			if (GetPersonnelGSCInCase(userConnection, id))
			{
				UpdatePersonnelGSCInCase(userConnection, id, portalMessage);
			}	
		}

		private bool GetPersonnelGSCInCase(UserConnection userConnection, Guid CaseId)
		{
			var select = new Select(userConnection).Column("SibPersonnelGSCId").From("Case").Where("Id").IsEqual(Column.Parameter(CaseId)) as Select;
			var personnelGSCId = select.ExecuteScalar<Guid>();
			if (personnelGSCId != Guid.Empty){
				return true;
			}else{
				return false;
			}			
		}

		private void UpdatePersonnelGSCInCase(UserConnection userConnection, Guid CaseId, string portalMessage)
		{
			var selectPersonnelGSC = new Select(userConnection).Column("SibPersonnelGSCId").From("Case").Where("Id").IsEqual(Column.Parameter(CaseId)) as Select;
			var personnelGSCId = selectPersonnelGSC.ExecuteScalar<Guid>();
			var selectComment =  new Select(userConnection).Column("SibPortalMessage").From("SibPersonnelGSC").Where("Id").IsEqual(Column.Parameter(personnelGSCId)) as Select;
			var comment = selectComment.ExecuteScalar<String>();
			var subString = "Комментарий";
			int index = portalMessage.IndexOf(subString, 0);
			var date = DateTime.Now;

			if (index > -1)
			{
				portalMessage = "Дата: " + date.ToString("dd.MM.yyyy hh:mm") + "\n" + portalMessage.Insert(index, "\n");
			}
			var concatComment = "";

			if (comment == String.Empty)
			{
				concatComment = portalMessage;
			}else{
				concatComment = comment + "\n\n" + portalMessage;
			}

			Update update = new Update(userConnection, "SibPersonnelGSC")
			.Set("SibPortalMessage", Column.Parameter(concatComment))
			.Where("Id").IsEqual(Column.Parameter(personnelGSCId)) as Update;
			update.Execute();
			}
	}
	#endregion

}
#endregion

