checkARCaseFile: function(id, callback) {
	var select = this.Ext.create("Terrasoft.EntitySchemaQuery", {
		rootSchemaName: "SibAccountReconciliationCaseFile"
	});
	select.addAggregationSchemaColumn("Id", Terrasoft.AggregationType.COUNT, "COUNT");
	select.filters.addItem(this.Terrasoft.createColumnFilterWithParameter(Terrasoft.ComparisonType.EQUAL,
		"Case", id));
	result = select.getEntityCollection(function(response) {
		if (response.success) {
			var selectResult = response.collection.getByIndex(0);
			var count = selectResult.get("COUNT");
			if	(count > 0 ){
				callback.call(this, true);
			}else{
				callback.call(this, false);
			}
		} else if (response.errorInfo) {
			callback.call(this, false);
		}
	}, this);
}

