if (!Date.prototype.toSQLString) {
	(function () {
		function pad(number) {
			if (number < 10) {
				return "0" + number;
			}
			return number;
		}

		Date.prototype.toSQLOString = function () {
			return (
				this.getUTCFullYear() +
				"-" +
				pad(this.getUTCMonth() + 1) +
				"-" +
				pad(this.getUTCDate()) +
				" " +
				pad(this.getUTCHours()) +
				":" +
				pad(this.getUTCMinutes()) +
				":" +
				pad(this.getUTCSeconds())
			);
		};
	})();
}

function getTableCaption(tableName, callback) {
	var select = Ext.create("Terrasoft.EntitySchemaQuery", {
		rootSchemaName: "SysSchema",
	});
	select.addColumn("Caption");
	select.filters.add(
		"Filter",
		this.Terrasoft.createColumnFilterWithParameter(
			Terrasoft.ComparisonType.EQUAL,
			"Name",
			tableName
		)
	);
	select.getEntityCollection(function (result) {
		if (result.success) {
			var caption = result.collection.collection.items[0].get("Caption");
			callback.call(this, caption);
		}
	}, this);
}

function getLookups(tableName, callback) {
	var select = Ext.create("Terrasoft.EntitySchemaQuery", {
		rootSchemaName: tableName,
	});
	select.allColumns = true;
	select.rowCount = 1;
	select.getEntityCollection(function (result) {
		if (result.success) {
			var results = [];
			result.collection.each(function (item) {
				for (var el in item.columns) {
					if (item.columns[el].referenceSchemaName) {
						results.push(item.columns[el].referenceSchemaName);
					}
				}
			});
			callback.call(this, results.filter(onlyUnique));
		}
	}, this);
}

function exportValues(tables) {
	debugger;
	for (var el in tables)
		(function (el) {
			var tablename = tables[el];
			var select = Ext.create("Terrasoft.EntitySchemaQuery", {
				rootSchemaName: tablename,
			});
			select.allColumns = true;
			select.rowCount = rowCount;
			select.getEntityCollection(function (result) {
				if (result.success) {
					var script = "";
					var item = result.collection.collection.items[0].values;
					for (var el in result.collection.collection.items[0]
						.values) {
						if (!excludeColumns.includes(el)) {
							script += el + ";";
						}
					}
					script = script.slice(0, -1);
					script += "\r\n";

					result.collection.each(function (item) {
						var insertStr = "";

						for (var el in item.values) {
							var value = item.values[el];

							if (value && value.value) {
								value = value.displayValue;
							}

							if (!excludeColumns.includes(el)) {
								insertStr += value + ";";
							}
						}
						insertStr = insertStr.slice(0, -1);
						insertStr += "\r\n";
						script += insertStr;
					});

					getTableCaption(tablename, function (caption) {
						download(caption + ".csv", script);
					});
				}
			}, this);
		})(el);
}

