			addColumnToEsq: function (esq) {
				this.callParent(arguments);
				var array = ["SolutionDate", "RegisteredOn", "Status"];
				for (var i = 0; i < array.length; i++) {
					if (!esq.columns.contains(array[i])) {
						esq.addColumn(array[i]);
					}
				}
			},
			//подкрашивает Обращения по которым прошло 75% срока SLA или просрочен срок SLA
			prepareResponseCollectionItem: function (item) {
				this.callParent(arguments);
				var currentDate = new Date();
				var solutionDate = item?.get("SolutionDate");
				var registeredDate = item?.get("RegisteredOn");
				var statusResolved = SibConstants.CaseStatus.Resolved; //решено
				var statusClosed = SibConstants.CaseStatus.Closed; //закрыто
				var deltaPersent =
					100 *
					Math.abs(
						(registeredDate - currentDate) /
							(registeredDate - solutionDate)
					);
				var status = item?.get("Status").displayValue;
				item.customStyle = null;
				if (status != statusResolved && status != statusClosed) {
					if (deltaPersent) {
						if (solutionDate && deltaPersent >= 75) {
							item.customStyle = {
								color: "black",
								background: "#f5d572", //желтый
							};
						}
					}
					if (solutionDate && solutionDate < currentDate) {
						item.customStyle = {
							color: "black",
							background: "#ffb0bb", //красный
						};
					}
				}
			},
		},
	};
});

