namespace Terrasoft.Configuration
{
	using System.ServiceModel;
	using System.ServiceModel.Activation;
	using System.ServiceModel.Web;
	using System.Web;
	using Terrasoft.Core;
	using Terrasoft.Web.Common;

	[ServiceContract]
	[AspNetCompatibilityRequirements(RequirementsMode = AspNetCompatibilityRequirementsMode.Required)]
	public class SibSetContactParam : BaseService
	{
		[OperationContract]
		[WebInvoke(Method = "POST", RequestFormat = WebMessageFormat.Json, BodyStyle = WebMessageBodyStyle.Wrapped,
        ResponseFormat = WebMessageFormat.Json)]
		public string CustomMethod(string inn, string phoneNumber)
		{
			var esq = new EntitySchemaQuery(UserConnection.EntitySchemaManager, "Contact");
			esq.Filters.Add(esq.CreateFilterWithParameters(FilterComparisonType.Equal, "INN", inn));
			EntityCollection entities = esq.GetEntityCollection(UserConnection);
			foreach (var entity in entities)
			{			
				entity.SetDefColumnValues();
				entity.SetColumnValue("SibCustomerPhoneNumber", phoneNumber);
				entity.Save();
			}			
			return "Update completed successfully";
		}


	}
}

