            var existsFilter = null;
            var existsCollection = [];
            if (result.success) {
                result.collection.each(function(item) {
                    existsCollection.push(item.get("MscControlEventTypeId"));
                });
            }
            if (existsCollection.length > 0) {
                existsFilter = Terrasoft.createColumnInFilterWithParameters("Id", existsCollection);
                existsFilter.comparisonType = Terrasoft.ComparisonType.NOT_EQUAL;
            }
            this.Ext.callback(callback, this, [existsFilter]);
        }, this);
    }
