		function calculationSum(){
			var collection = getAllValue();
			if(collection){			
				var r = collection.isUrgently == true ? 1.5 : 1;// НУЖНО ДОБАВИТЬ	
				var PP = collection.isPremiumTransaction == true ? 3 : 1;
				var endAllSum = 0;//итоговая сумма которую нужно записать в поле
				let result = collection.fields;			
				for (let key in result) {	
					var allVal =  result[key];
					var format = allVal['Формат'];			  
					var countPage = allVal['Количество страниц'];				
					var n = countPage;		  				
					var k = format == 'Редактируемый' ? 0 : 120;				
					var groupVal = allVal.groups;// коллекция подуслуг для каждого комплекта
					var C_all = 0;
					var R_All = 0;
					var sumOneRecord = 0;
					for (let gr in groupVal) {

						var geVal =  groupVal[gr];
						var subservice = geVal['Подуслуга']; 
						var D = geVal['Количество экземпляров'];
						var direction = geVal['Направление'];
						if(direction){
							C_all += subservice == "Письменный перевод" ? getIntPay(direction) : 0;				
							R_All += subservice == "Сверка/редактирование ранее выполненных переводов" ? (getIntPay(direction) * 0.5) : 0;
							var Z = subservice == "Оформление нотариального заверения" ? 810 : 0;
