define("AccountAddressPageV2", [], function () {
	return {
		entitySchemaName: "AccountAddress",
		methods: {
			asyncValidate: function (callback, scope) {
				this.callParent([
					function (response) {
						if (response.success) {
							this.AccountAddressValidator(callback);
						} else {
							callback.call(scope, response);
						}
					},
					this,
				]);
			},
			AccountAddressValidator: function (callback) {
				var esq = Ext.create("BPMSoft.EntitySchemaQuery", {
					rootSchemaName: "AccountAddress",
				});
				esq.addColumn("Account", "AddressType");
				esq.filters.add(
					BPMSoft.generateGUID(),
					esq.createColumnFilterWithParameter(
						this.BPMSoft.ComparisonType.EQUAL,
						"Account",
						this.get("Account").value
					)
				);
				esq.filters.add(
					BPMSoft.generateGUID(),
					esq.createColumnFilterWithParameter(
						this.BPMSoft.ComparisonType.EQUAL,
						"AddressType",
						this.get("AddressType").value
					)
				);

				esq.getEntityCollection(function (result) {
					if (result.success) {
						if (result.collection.collection.length > 0) {
							callback.call(this, {
								success: false,
								message: Ext.String.format(
									this.get(
										"Resources.Strings.InvalidAddressType"
