namespace Terrasoft.Configuration.GetReportFileService
{
    using System;
    using System.Globalization;
    using System.IO;
    using System.ServiceModel;
    using System.ServiceModel.Activation;
    using System.ServiceModel.Web;
    using System.Text.RegularExpressions;
    using System.Web.SessionState;
    using Terrasoft.Common;
    using Terrasoft.Web.Common;
    using System.Web;

    #region Class: GetReportFileService

    [ServiceContract]
    [AspNetCompatibilityRequirements(RequirementsMode = AspNetCompatibilityRequirementsMode.Required)]
    public class GetReportFileService : BaseService, IReadOnlySessionState
    {
        private HttpContext CurrentContext => HttpContext.Current;

        [OperationContract]
        [WebGet(UriTemplate = "GetReportFile/{cacheKey}/{fileNameCode}")]
        public void GetReportFile(string cacheKey, string fileNameCode)
        {
            object reportObj = UserConnection.SessionData[cacheKey];
            var memoryStream = new MemoryStream((byte[])reportObj);
            UserConnection.SessionData.Remove(cacheKey);
            PrepareContext(memoryStream, $"{fileNameCode}.xlsx"); 
        }

        #region Methods: Private
        private string RemoveSpecialCharacters(string fileName)
        {
            return Regex.Replace(fileName, @"[^a-zA-Z\p{IsCyrillic}0-9_.,^&@£$€!½§~'=()\[\]{} «»<>~#*%+-]+",
                "_", RegexOptions.Compiled);
        }
        private void PrepareContext(MemoryStream memoryStream, string reportFileName)
        {
            if (memoryStream == null)
            {
                CurrentContext.Response.StatusCode = (int)System.Net.HttpStatusCode.NotFound;
                CurrentContext.Response.StatusDescription = "Ошибка формирования отчета";
                return;
            }
            CurrentContext.Response.ContentType = "application/octet-stream";
            CurrentContext.Response.Headers["Content-Length"] = memoryStream.Length.ToString(CultureInfo.InvariantCulture);
            string contentDisposition = GetResponseContentDisposition(reportFileName);
            CurrentContext.Response.AddHeader("Content-Disposition", contentDisposition);
            MimeTypeResult mimeTypeResult = MimeTypeDetector.GetMimeType(reportFileName);
            if (mimeTypeResult.HasError) CurrentContext.Response.ContentType = mimeTypeResult.Type;
            memoryStream.Flush();
            memoryStream.WriteTo(CurrentContext.Response.OutputStream);
            memoryStream.Dispose();
        }
        #endregion

        #region Methods: Protected
        /// <summary>
        /// Gets response content disposition header value.
        /// </summary>
        /// <param name="fileName">File name.</param>
        /// <returns>Content disposition header value.</returns>
        protected virtual string GetResponseContentDisposition(string fileName)
        {
            string processedFileName;
            HttpRequest request = CurrentContext.Request;
            string userAgent = (request.UserAgent ?? String.Empty).ToLowerInvariant();
            if (userAgent.Contains("android"))
            {
                processedFileName = $"filename=\"{RemoveSpecialCharacters(fileName)}\"";
            }
            else if (userAgent.Contains("safari"))
            {
                processedFileName = $"filename*=UTF-8''{HttpUtility.UrlEncode(fileName)}";
            }
            else
            {
                processedFileName = $"filename=\"{fileName}\"; filename*=UTF-8''{HttpUtility.UrlEncode(fileName)}";
            }
            return $"attachment; {processedFileName}";
        }
        #endregion
    }
    #endregion
}

