define("BaseFileProcessingUserTaskPropertiesPage", [
	"BaseFileProcessingUserTaskPropertiesPageResources",
	"ProcessSchemaUserTaskUtilities",
	"EntitySchemaDesignerUtilities",
	"ProcessUserTaskConstants",
	"FilterModuleMixin",
	"SortingOrderControlsMixin",
], function (resources, userTaskUtilities) {
	return {
		properties: {
			_defaultResultActionType:
				Terrasoft.ProcessUserTaskConstants
					.ObjectFileProcessingUserTaskResultActionType.UseInProcess,
		},
		mixins: {
			filterModuleMixin: "Terrasoft.FilterModuleMixin",
		},
		messages: {},
		attributes: {},
		methods: {
			/**
			 * @private
			 */
			_getReferencedSchemas: function (
				entitySchemaUIdList,
				callback,
				scope
			) {
				const packageUId = this.get("packageUId");
				this.getFileEntities(
					packageUId,
					entitySchemaUIdList,
					callback,
					scope
				);
			},

			/**
			 * Returns file entities collection.
			 * @param {Guid} packageUId Package unique identifier.
			 * @param {Array} entitySchemaUIdList Optional array of entity schema unique identifiers to filter entities by.
			 * @param {Function} callback Callback.
			 * @param {Object} scope Scope object.
			 */
			getFileEntities: function (
				packageUId,
				entitySchemaUIdList,
				callback,
				scope
			) {
				const fileEntityNames = Ext.create("Terrasoft.Collection");
				Terrasoft.each(
					Terrasoft.configuration.ModuleStructure,
					function (item) {
						if (item.entitySchemaUId) {
							const fileEntitySchemaName =
								item.entitySchemaName === "Lead"
									? "FileLead"
									: Ext.String.format(
											"{0}File",
											item.entitySchemaName
									  );
							fileEntityNames.add(fileEntitySchemaName, {
								entitySchemaUId: item.entitySchemaUId
									.toLowerCase()
									.replace(/[{}]/g, ""),
								entitySchemaName: item.entitySchemaName,
							});
						}
					},
					this
				);
				fileEntityNames.add("SibTranslateDocuments", {
					entitySchemaUId: "e0157833-6407-43a8-a86d-e2001ba20ce7",
					entitySchemaName: "SibCaseInfoTranslation",
				});
				Terrasoft.EntitySchemaManager.findPackageItems(
					packageUId,
					(entities) => {
						entities.sort("caption", Terrasoft.OrderDirection.ASC);
						const filteredEntities = entities
							.filter((item) => !item.getIsVirtual())
							.filter((item) =>
								fileEntityNames.contains(item.getName())
							)
							.filter(
								(item) =>
									!entitySchemaUIdList ||
									(entitySchemaUIdList &&
										Terrasoft.contains(
											entitySchemaUIdList,
											item.getUId()
										))
							);
						const resultEntities = {};
						filteredEntities.each(function (entity) {
							const entitySchemaUId = entity.getUId();
							const schemaSchemaName = entity.getName();
							const entityFileInfo =
								fileEntityNames.get(schemaSchemaName);
							resultEntities[entitySchemaUId] =
								this._createSelectItem(entity, entityFileInfo);
						}, this);
						Ext.callback(callback, scope, [resultEntities]);
					},
					this
				);
			},

			/**
			 * @private
			 */
			_createSelectItem: function (schemaItem, entityFileInfo) {
				return {
					value: schemaItem.getUId(),
					displayValue: schemaItem.getCaption(),
					name: schemaItem.getName(),
					entitySchemaUId: entityFileInfo.entitySchemaUId,
					entitySchemaName: entityFileInfo.entitySchemaName,
				};
			},
		},
		diff: /**SCHEMA_DIFF*/ [] /**SCHEMA_DIFF*/,
	};
});

