		public List<string> GetEmailList()
		{
			var result = new List<string>();
			SqlCommand command = new SqlCommand(
				@"select DISTINCT Email 
				from Contact 
				join Contract on Contract.ContactId = Contact.Id 
				where DATEDIFF(day, Contract.SignedDate, CAST(GETDATE() AS DATE)) <= 30 and Contract.Amount > 40000",
				Connection);

			using (SqlDataReader reader = command.ExecuteReader())
			{
				while (reader.Read())
				{
					result.Add(reader["Email"].ToString());
				}
			}
			return result;
		}

		public string GetContractAmount()
		{
			SqlCommand command = new SqlCommand("Select SUM(Amount) from [Contract] where YEAR([SignedDate]) = YEAR(GETDATE())", Connection);
			if (Convert.IsDBNull(command))
			{
				return "Записей не найдено.";
			}
			return Convert.ToString(command.ExecuteScalar());
		}

