﻿using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using Newtonsoft.Json;

namespace SixtyNamesTestTask
{
	internal class Program
	{
		static void Main(string[] args)
		{

			var dataHelper = new DataHelper();
			while (true) { 
				switch (new Menu().Print())
				{
					case ConsoleKey.D1:
						Console.WriteLine();
						var contractAmount = dataHelper.GetContractAmount();
						Console.WriteLine("Результат: " + contractAmount);
						Console.WriteLine();
						break;
					case ConsoleKey.D2:
						Console.WriteLine();
						var contractAmountRu = dataHelper.GetContractAmountRu();
						Console.WriteLine("Результат: " + contractAmountRu);
						Console.WriteLine();
						break;						
					case ConsoleKey.D3:
						Console.WriteLine();
						var emails = dataHelper.GetEmailList();
						int i = 1;
						if (emails.Count == 0)
						{
							Console.WriteLine("Результат: Записей не найдено.");
						}
						foreach (var email in emails)
						{
							if (!String.IsNullOrEmpty(email))
							{
								Console.WriteLine(String.Format("Результат {0}: ", i) + email);
								i++;
							}
						}
						Console.WriteLine();
						break;
					case ConsoleKey.D4:
						Console.WriteLine();
						dataHelper.UpdateContractStatus();
						Console.WriteLine("Выполнено.");
						Console.WriteLine();
						break;
					case ConsoleKey.D5:
						dataHelper.CreateReport();
						Console.WriteLine();
						Console.WriteLine(dataHelper.CreateReport());
						break;
					default:
						Environment.Exit(0);
						break;
